import zlib, struct
def load_png(path):
    data=open(path,'rb').read(); assert data[:8]==b'\x89PNG\r\n\x1a\n'
    pos=8; idat=b''; W=H=bt=ct=None
    while pos<len(data):
        ln=struct.unpack('>I',data[pos:pos+4])[0]; pos+=4; typ=data[pos:pos+4]; pos+=4; ch=data[pos:pos+ln]; pos+=ln+4
        if typ==b'IHDR': W,H,bt,ct,_,_,_=struct.unpack('>IIBBBBB',ch)
        elif typ==b'IDAT': idat+=ch
        elif typ==b'IEND': break
    raw=zlib.decompress(idat); ch={2:3,6:4,0:1,4:2}[ct]; stride=W*ch; out=bytearray(); prev=bytearray(stride); p=0
    for y in range(H):
        ft=raw[p]; p+=1; line=bytearray(raw[p:p+stride]); p+=stride
        for i in range(stride):
            a=line[i-ch] if i>=ch else 0; b=prev[i]; c=prev[i-ch] if i>=ch else 0
            if ft==1: line[i]=(line[i]+a)&255
